						kind: 'type',
						name: 'CliSecretBroker',
						signature:
							'type CliSecretBroker = {\n    resolve: (name: string) => Promise<SecretValue | null>;\n    rotate: (name: string) => Promise<SecretValue>;\n    fingerprint: (value: string) => string;\n};'
