						code: "app.use({\n  stt: gladia({ apiKey, codeSwitching: true }),\n  // and at open() time:\n  // languageStrategy: { mode: 'allow-switching', primaryLanguage: 'en', secondaryLanguages: ['hi'] }\n});",
