				readmeSamples: [
					{
						code: 'import { createOsvAdapter } from "@absolutejs/vulnerabilities-osv";\nimport { createMemoryFeedStore, syncFeed } from "@absolutejs/vulnerabilities";\n\nconst adapter = createOsvAdapter({\n  queries: [\n    {\n      package: { ecosystem: "npm", name: "lodash" },\n      version: "4.17.20",\n    },\n  ],\n});\n\nconst result = await syncFeed({\n  adapter,\n  maxStaleMs: 24 * 60 * 60 * 1_000,\n  store: createMemoryFeedStore(),\n});',
						description: '# @absolutejs/vulnerabilities-osv',
						heading: '@absolutejs/vulnerabilities-osv quick start',
						language: 'typescript'
					}
				],
				readmeTopics: [
					{
						description:
							'Official OSV API ingestion for @absolutejs/vulnerabilities. The package normalizes OSV records into the shared advisory contract, preserves aliases, affected package ranges, CVSS vectors, and source provenance, and follows per-query pagination from the OSV batch API.',
						details: [
							'Each batch result remains aligned with its source query. Pagination tokens are followed independently, advisory identifiers are deduplicated, and each full record is retrieved from the official OSV API before normalization.'
						],
						title: 'Overview'
					}
				],
				sourcePath: 'osv',
				version: '0.1.8'
